import { notFound } from "next/navigation";
import Header from "@/components/Header";
import Footer from "@/components/Footer";
import HeroSlider from "@/components/HeroSlider";
import ProjectGallery from "@/components/ProjectGallery";
import OtherProjects from "@/components/OtherProjects";
import ProjectSideNav from "@/components/ProjectSideNav";
import { getProjectPageData } from "@/lib/project-page";

export const revalidate = 60;

export default async function ProjectPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const data = await getProjectPageData(slug);

  if (!data) notFound();

  const { project, previous, next, others } = data;

  const heroImages = Array.isArray(project.hero_images)
    ? project.hero_images
    : project.hero_image
      ? [project.hero_image]
      : [];

  const galleryImages = Array.isArray(project.gallery_images)
    ? project.gallery_images
    : [];

  return (
    <>
      <Header />

      <main className="project-detail-page">
        <section className="project-detail-heading">
          <h1>{project.title}</h1>
        </section>

        {heroImages.length > 0 && (
          <section className="project-detail-hero">
            <HeroSlider
              images={heroImages}
              title={project.title}
            />
          </section>
        )}

        {(project.location || project.area || project.year || project.description) && (
          <section className="project-detail-content">
            <div className="project-detail-copy">
              {(project.location || project.area || project.year) && (
                <h2>
                  {[project.location, project.area, project.year]
                    .filter(Boolean)
                    .join(" | ")}
                </h2>
              )}

              {project.description &&
                String(project.description)
                  .split(/\n+/)
                  .map((paragraph) => paragraph.trim())
                  .filter(Boolean)
                  .map((paragraph, index) => (
                    <p key={index}>{paragraph}</p>
                  ))}
            </div>
          </section>
        )}

        <ProjectGallery
          images={galleryImages}
          title={project.title}
        />

        <OtherProjects projects={others} />
      </main>

      <ProjectSideNav previous={previous} next={next} />

      <Footer />
    </>
  );
}
